# Generated by build.py from recipe.yml for recipe http-tell-which-listener-was-used. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "id,total`n1,40`n")
[IO.File]::WriteAllText((Join-Path $PWD 'token.txt'), "listener-recipe-control-token-0123456789`n")
[IO.File]::WriteAllText((Join-Path $PWD 'control.hdr'), "Authorization: Bearer listener-recipe-control-token-0123456789`n")
[IO.File]::WriteAllText((Join-Path $PWD 'which-listener.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# For each exchange: the listen URL that took it, from surl's control endpoint, beside what`n# the trace says (the listen URL on its Exchange opened line, and for HTTP the Host header the client sent).`n# Run: sh which-listener.sh <control URL>   (control.hdr holds the token header)`ncontrol=`$1`ncount() { curl -s -H @control.hdr `"`${control}v1/events?kind=`$1`" | grep -o '`"exchange_id`"' | grep -c .; }`n`n# The record is whole once every exchange that started has ended: wait, at most 10 s.`ntries=0`nuntil [ `"`$(count exchange_ended)`" -eq `"`$(count exchange_started)`" ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 50 ]; then echo `"the exchanges did not end within 10 s`"; exit 1; fi`n  sleep 0.2`ndone`n`ncurl -s -H @control.hdr `"`${control}v1/events?kind=exchange_started`" |`n  grep -o '`"exchange_id`":[0-9]*,`"listen_url`":`"[^`"]*`"' | tr -d '`"' | sed 's/exchange_id://; s/,listen_url:/ /' |`n  while read -r id url; do`n    listener=`$(grep `"^#`$id \* Exchange `$id opened: `" trace.txt | sed 's/.* opened: [a-z]* on \([^ ]*\) from .*/\1/')`n    host=`$(awk -v mark=`"#`$id `" '`n      index(`$0, `"#`") == 1 { inside = (index(`$0, mark `"<= Recv`") == 1); next }`n      inside && / Host: / { sub(/.* Host: /, `"`"); sub(/\r`$/, `"`"); print; exit }' trace.txt)`n    echo `"exchange `$id: `$url  trace: `$listener`${host:+, Host `$host}`"`n  done`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'site', '--log-file', 'surl.log', '--trace-ascii', 'trace.txt', '--control', 'http://127.0.0.1:8083/', '--control-token-file', 'token.txt', 'http://127.0.0.1:8080/', 'http://127.0.0.1:8081/', 'ftp://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -s --retry 30 --retry-connrefused --retry-delay 1 -o NUL -H @control.hdr http://127.0.0.1:8083/v1/events
try { sh which-listener.sh http://127.0.0.1:8083/ } finally { Stop-Process $server0 }
